@'
const fs = require("fs");
const text = fs.readFileSync("semio/react/index.tsx", "utf8");
const marker = "const SCHEMA_MANIFEST = `";
const start = text.indexOf(marker);
if (start < 0) throw new Error("manifest start");
const afterStart = start + marker.length;
const end = text.indexOf("`;", afterStart);
if (end < 0) throw new Error("manifest end");
const manifest = text.slice(afterStart, end).trim();
const defs = manifest.split(/\r?\n/).filter(Boolean).map((line) => {
  const [head, tail = ""] = line.split(":");
  const [kind, name] = head.trim().split(/\s+/);
  return { kind, name, fields: tail ? tail.split(",").filter(Boolean) : [] };
});
const providerKinds = ["Piece", "Type", "Design", "Connection", "Port", "Quality", "File", "Folder", "Author", "Tag", "Concept", "Family", "Representation", "Connector", "Benchmark", "Layer", "Group", "Stat", "Prop", "Attribute"];
const pascal = (value) => value ? value[0].toUpperCase() + value.slice(1) : value;
const providers = providerKinds.map((name) => `export function ${name}Provider({ guid: guidValue, children }: { guid?: string; children: ReactNode }): React.ReactElement {\n\tconst scope = useEntityScope("${name}", guidValue);\n\treturn React.createElement(SchemaScopeContext.Provider, { value: scope }, children);\n}`).join("\n\n");
const hooks = [];
const hookObjectEntries = [];
const propertyHooks = [];
for (const def of defs) {
  hooks.push(`export function use${def.name}(guidValue?: string): SchemaHookTriad<any> {\n\treturn useSchemaObjectState("${def.name}", guidValue);\n}`);
  hookObjectEntries.push(`\tuse${def.name},`);
  for (const field of def.fields) {
    const hookName = `use${def.name}${pascal(field)}`;
    hooks.push(`export function ${hookName}(guidValue?: string): SchemaHookTriad<any> {\n\treturn useSchemaFieldState("${def.name}", "${field}", guidValue);\n}`);
    hookObjectEntries.push(`\t${hookName},`);
    propertyHooks.push(`\t${hookName},`);
  }
}
console.log("---PROVIDERS---");
console.log(providers);
console.log("---HOOKS---");
console.log(hooks.join("\n\n"));
console.log("---SCHEMA_HOOKS---");
console.log(`export const schemaHooks = Object.freeze({\n${hookObjectEntries.join("\n")}\n});`);
console.log("---ALL_PROPERTY_HOOKS---");
console.log(`const ALL_PROPERTY_HOOKS = Object.freeze([\n${propertyHooks.join("\n")}\n] as const);`);
console.log("---COUNTS---");
console.log(JSON.stringify({ kinds: defs.length, propertyHooks: propertyHooks.length }));
